-- returnLoan: Return a loan
-- Changes exactly 1 Loan record of table loans: sets status to returned, from open or overdue, by id, where status == "open" || status == "overdue".
-- Dry run: psql -v ON_ERROR_STOP=1 -v id=... -v last_modified_by_user_id=... -v last_modified_by_user_nameid=... -f return-loan.sql
-- Apply: the same with -v apply=true. Without it every check runs against the data and the change is rolled back.
\set ON_ERROR_STOP on
\set QUIET on
\if :{?apply}
\else
\set apply false
\endif
\if :{?id}
\else
DO $script$ BEGIN RAISE EXCEPTION 'return-loan.sql: the variable id is not set; give it as psql -v id=<Loan.id> (UUID)'; END $script$;
\endif
\if :{?last_modified_by_user_id}
\else
DO $script$ BEGIN RAISE EXCEPTION 'return-loan.sql: the variable last_modified_by_user_id is not set; give it as psql -v last_modified_by_user_id=<last_modified_by_user_id> (VARCHAR(255))'; END $script$;
\endif
\if :{?last_modified_by_user_nameid}
\else
DO $script$ BEGIN RAISE EXCEPTION 'return-loan.sql: the variable last_modified_by_user_nameid is not set; give it as psql -v last_modified_by_user_nameid=<last_modified_by_user_nameid> (VARCHAR(255))'; END $script$;
\endif
BEGIN;
SET LOCAL specarch.apply = :'apply';
SET LOCAL specarch.id = :'id';
SET LOCAL specarch.last_modified_by_user_id = :'last_modified_by_user_id';
SET LOCAL specarch.last_modified_by_user_nameid = :'last_modified_by_user_nameid';
DO $script$
DECLARE
  found bigint;
  changed bigint;
BEGIN
  -- 1. Already applied: the record already holds what the change writes.
  IF EXISTS (SELECT 1 FROM loans WHERE id = current_setting('specarch.id', true)::UUID AND status = 'returned') THEN
    RAISE NOTICE 'operation returnLoan: the Loan with id % already holds status returned; nothing to change', current_setting('specarch.id', true)::UUID;
    RETURN;
  END IF;
  -- 2. Precondition: exactly 1 Loan record to change, locked until the end.
  SELECT count(*) INTO found FROM (SELECT 1 FROM loans WHERE id = current_setting('specarch.id', true)::UUID
    AND status IN ('open', 'overdue')
    AND ((status = 'open') OR (status = 'overdue'))
    AND is_deleted = false FOR UPDATE) AS records;
  IF found <> 1 THEN
    RAISE EXCEPTION 'operation returnLoan: % Loan records hold id %, status open or overdue, status == "open" || status == "overdue", not deleted, and the change expects exactly 1; nothing was changed', found, current_setting('specarch.id', true)::UUID;
  END IF;
  -- 3. The change, under the same condition.
  UPDATE loans
  SET status = 'returned',
      last_modified_at = now(),
      last_modified_by_user_id = current_setting('specarch.last_modified_by_user_id', true)::VARCHAR,
      last_modified_by_user_nameid = current_setting('specarch.last_modified_by_user_nameid', true)::VARCHAR
  WHERE id = current_setting('specarch.id', true)::UUID
    AND status IN ('open', 'overdue')
    AND ((status = 'open') OR (status = 'overdue'))
    AND is_deleted = false;
  GET DIAGNOSTICS changed = ROW_COUNT;
  -- 4. Postcondition: the exact count, and the record holds what was written.
  IF changed <> 1 THEN
    RAISE EXCEPTION 'operation returnLoan: the change wrote % Loan records, and exactly 1 was expected; another writer may have changed them after they were counted; nothing was changed', changed;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM loans WHERE id = current_setting('specarch.id', true)::UUID AND status = 'returned') THEN
    RAISE EXCEPTION 'operation returnLoan: after the change the Loan with id % does not hold status returned; nothing was changed', current_setting('specarch.id', true)::UUID;
  END IF;
  -- 5. Dry run unless apply is true.
  IF current_setting('specarch.apply')::boolean THEN
    RAISE NOTICE 'operation returnLoan: 1 Loan record changed; committing';
  ELSE
    RAISE NOTICE 'operation returnLoan: dry run: 1 Loan record would change, and every check passed; rolling back. Run it again with -v apply=true to make the change';
  END IF;
END
$script$;
\if :apply
